  `before_login_bin_data` blob DEFAULT NULL COMMENT 'login前用的数据（对比extra_bin_data没有多写的问题）'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='玩家核心数据包';

